add_filter( 'intermediate_image_sizes_advanced', 'perfectpixel_disable_image_sizes', 20 );

function perfectpixel_disable_image_sizes( $sizes ) {
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{disabled_image_sizes}}' ) ) ) as $name ) {
		unset( $sizes[ $name ] );
	}
	return $sizes;
}
